const MOL_MAP={"Ácido Hialurónico 1%":"Hyaxum","Ácido Hialurónico 1.5%":"Hyaxum","Ácido Hialurónico 2%":"Hyaxum","Bevacizumab 100":"Bevacizumab","Bevacizumab 400":"Bevacizumab","Hyaxum 1":"Hyaxum","Hyaxum 1.5 Plus":"Hyaxum","Hyaxum 2 Pro":"Hyaxum","Euxara":"Euxara","Fixed":"Fixed","ACHI":"Hyaxum","BEVA":"Bevacizumab","TERI":"Euxara","FIXED":"Fixed","PELI":"Peli","DENO":"Denosumab","Deno":"Denosumab","Teriparatida":"Euxara","SIME":"Sime","ACMI":"Acmi","Hyaxum 2% Pro":"Hyaxum","Hyaxum 1.5% Plus":"Hyaxum","Hyaxum 1.5 % Plus":"Hyaxum","Ezetimiba  10mg. + Atorvastatina 20 mg.":"Ezetimiba + Atorvastatina 10/20mg","Certolizumab 200mg/ml PFS":"Certolizumab 200mg/ml PFS","Certolizumab 200mg/ml Vial":"Certolizumab 200mg/ml Vial","Ezetimiba + Atorvastatina 10/20mg":"Ezetimiba + Atorvastatina 10/20mg","Ezetimiba + Atorvastatina 10/40mg":"Ezetimiba + Atorvastatina 10/40mg","Penpulimab":"Penpulimab"};
